import React from "react";
import { Link, useNavigate } from "react-router-dom";

const Header = () => {
  const navigate = useNavigate();
  return (
    <div className="header">
      <header className="header-content" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', width: '100%' }}>
        <div className="logo" style={{ fontWeight: 800, fontSize: '2rem', letterSpacing: '2px', color: 'var(--color-primary)', padding: '0 12px' }}>
          INVENTORY
        </div>
        <nav className="links" style={{ display: 'flex', gap: '36px', fontSize: '1.1rem', fontWeight: 600 }}>
          <Link to="/home">HOME</Link>
          <Link to="/products">PRODUCTS</Link>
          <Link to="/category">CATEGORIES</Link>
          <Link to="/brand">BRANDS</Link>
        </nav>
        <button
          style={{
            background: "linear-gradient(90deg, #3498db 60%, #007bff 100%)",
            width: "120px",
            height: "38px",
            borderRadius: "8px",
            cursor: "pointer",
            color: "#fff",
            fontWeight: 600,
            fontSize: "15px",
            border: "none",
            marginLeft: '32px',
            boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
            transition: "background 0.2s, transform 0.2s"
          }}
          onClick={() => {
            localStorage.removeItem("token");
            navigate("/login");
          }}
          onMouseEnter={e => e.target.style.background = "linear-gradient(90deg, #2c80b4 60%, #0056b3 100%)"}
          onMouseLeave={e => e.target.style.background = "linear-gradient(90deg, #3498db 60%, #007bff 100%)"}
        >
          Logout
        </button>
      </header>
    </div>
  );
};

export default Header;
